def boolean_retrieval(query_terms, operator, index):
    # index maps term to set of doc IDs
    if operator == 'AND':
        result = set.intersection(*(index[t] for t in query_terms))
    elif operator == 'OR':
        result = set.union(*(index[t] for t in query_terms))
    elif operator == 'NOT':
        result = index[query_terms[0]] - index[query_terms[1]]
    return result

# Sample inverted index
inv_index = {'python': {1, 2, 3}, 'java': {2, 4}}
print(boolean_retrieval(['python', 'java'], 'AND', inv_index))

