def eval_query(index, t1, op1, t2, op2, t3):
    # evaluate sequentially for simplicity
    s1 = index.get(t1, set())
    s2 = index.get(t2, set())
    s3 = index.get(t3, set())
    if op1 == 'AND':
        res = s1.intersection(s2)
    else:
        res = s1.union(s2)
    if op2 == 'AND':
        return res.intersection(s3)
    else:
        return res.union(s3)

