# Demonstrating Skip Pointers in Postings List Intersection

class PostingNode:
    def __init__(self, doc_id):
        self.doc_id = doc_id
        self.skip = None

# Helper to build simple list with skips
def create_skip_list(nums):
    nodes = [PostingNode(n) for n in nums]
    skip_interval = int(len(nums) ** 0.5)
    for i in range(len(nodes)):
        if i + skip_interval < len(nodes):
            nodes[i].skip = nodes[i + skip_interval]
    return nodes

def intersect_with_skips(p1, p2):
    answer = []
    i, j = 0, 0
    while i < len(p1) and j < len(p2):
        if p1[i].doc_id == p2[j].doc_id:
            answer.append(p1[i].doc_id)
            i += 1
            j += 1
        elif p1[i].doc_id < p2[j].doc_id:
            # Use skip pointer if possible
            if p1[i].skip and p1[i].skip.doc_id <= p2[j].doc_id:
                while p1[i].skip and p1[i].skip.doc_id <= p2[j].doc_id:
                    i = p1.index(p1[i].skip)
            else:
                i += 1
        else:
            j += 1
    return answer

list1 = create_skip_list([2, 4, 6, 8, 10, 12, 14, 16])
list2 = create_skip_list([6, 12, 20])
print("Intersect with skips result:", intersect_with_skips(list1, list2))

