def e_step(X, P_z_d, P_w_z):
    # X: docs x terms, P_z_d: docs x topics, P_w_z: topics x terms
    num_docs, num_terms = X.shape
    num_topics = P_z_d.shape[1]
    P_z_dw = np.zeros((num_docs, num_terms, num_topics))
    for d in range(num_docs):
        for w in range(num_terms):
            numerator = P_z_d[d, :] * P_w_z[:, w]
            denominator = np.sum(numerator)
            if denominator > 0:
                P_z_dw[d, w, :] = numerator / denominator
    return P_z_dw

