import random

# Independent Cascade Model Simulation
def independent_cascade(graph, seeds, p=0.3):
    active = set(seeds)
    newly_active = set(seeds)

    while newly_active:
        next_active = set()
        for u in newly_active:
            for v in graph.get(u, []):
                if v not in active:
                    if random.random() < p:
                        active.add(v)
                        next_active.add(v)
        newly_active = next_active
    return active

