def threshold_step(graph, active_set, thresholds):
    new_active = set()
    for node, neighbors in graph.items():
        if node not in active_set:
            active_neighbors = sum(1 for n in neighbors if n in active_set)
            fraction = active_neighbors / len(neighbors) if neighbors else 0
            if fraction >= thresholds.get(node, 1.0):
                new_active.add(node)
    return new_active

